INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q01','{"text":"Em um jogo digital, qual elemento responde à pergunta “O que posso fazer?”?","options":["Mecânica","Regra","Desafio","Progressão","Experiência"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q02','{"text":"O core loop de um jogo é definido na apostila como:","options":["a sequência recorrente que sustenta a experiência","a ordem fixa das cenas do projeto","a lista de recursos gráficos do jogo","a quantidade de fases publicadas","o sistema de salvamento automático"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q03','{"text":"Segundo a apostila, qual marco de 1962 se tornou referência dos jogos em computador?","options":["Spacewar!","Pong","Odyssey","Tennis for Two","Pac-Man"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q04','{"text":"Na classificação apresentada, “mobile”, “multiplayer” e “pixel art” correspondem, respectivamente, a:","options":["plataforma, modo de participação e linguagem visual","gênero, plataforma e mecânica","mecânica, gênero e plataforma","linguagem visual, gênero e engine","modo, engine e plataforma"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q05','{"text":"Em um jogo de plataforma, quais sistemas aparecem como centrais no primeiro exercício sugerido?","options":["gravidade, salto, chão e câmera","inventário, diálogo, economia e crafting","turnos, recursos e regras de alvo","texto, escolhas e estados da história","rotas, alcance e prioridade"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q06','{"text":"Qual área da criação de jogos organiza desafios no espaço?","options":["Level design","Áudio","Narrativa","QA","Produção"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q07','{"text":"No ciclo de prototipação proposto, antes de produzir muita arte e conteúdo deve-se:","options":["testar uma hipótese com protótipo simples e observar alguém jogando","finalizar todas as fases","publicar a versão comercial","criar todos os efeitos sonoros","implementar multiplayer"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q08','{"text":"O GDevelop é apresentado na apostila como:","options":["motor e editor de jogos com programação visual por eventos e possibilidade de JavaScript","editor exclusivo de pixel art","banco de dados para jogos online","linguagem textual que substitui JavaScript","ferramenta apenas para jogos 3D"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q09','{"text":"No editor do GDevelop, qual área é usada para escrever condições e ações?","options":["Editor de eventos","Lista de objetos","Prévia","Gerenciador do projeto","Propriedades da instância"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q10','{"text":"No exemplo cristal.png → Cristal → dez cristais na fase, esses elementos são, respectivamente:","options":["recurso, objeto e instâncias","objeto, recurso e comportamentos","instância, objeto e recursos","recurso, comportamento e cenas","sprite, variável e eventos"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q11','{"text":"Qual afirmação diferencia corretamente objeto e instância?","options":["O objeto define um elemento; a instância é uma ocorrência desse objeto na cena","A instância define todas as cenas do projeto","Objeto e instância são sempre sinônimos","O objeto só existe durante a prévia","A instância não pode possuir dados próprios"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q12','{"text":"Uma spritesheet é:","options":["uma imagem que reúne vários quadros","uma camada exclusiva do HUD","um tipo de variável global","uma máscara de colisão","um temporizador de animação"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q13','{"text":"Oito quadros com duração de 0,10 segundo cada formam um ciclo de animação de:","options":["0,80 segundo","0,08 segundo","8 segundos","1,80 segundo","80 segundos"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q14','{"text":"Para evitar regras de animação incompatíveis, quando o personagem está morto a apostila recomenda que:","options":["a animação de morte tenha prioridade sobre a de corrida","todas as animações executem simultaneamente","a corrida continue indefinidamente","a spritesheet seja removida","a câmera escolha a animação"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q15','{"text":"Qual definição está de acordo com a apostila?","options":["Hitbox costuma ser área ofensiva e hurtbox a área que recebe ataques","Hitbox é o HUD e hurtbox é a câmera","Hitbox é sempre a imagem inteira","Hitbox e hurtbox são tipos de cena","Hurtbox serve para salvar o jogo"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q16','{"text":"Por que a máscara de colisão pode ser diferente do contorno visual completo do sprite?","options":["Detalhes transparentes ou decorativos podem não precisar bloquear movimento","Colisões só funcionam com imagens invisíveis","A máscara controla o volume do áudio","Todo sprite precisa de máscara do tamanho da tela","A máscara define a pontuação"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q17','{"text":"Para manter vida, coleta e objetivo legíveis enquanto o mundo se move, esses elementos devem ficar em tratamento próprio de:","options":["HUD e camada apropriada","parallax","hitbox ofensiva","pathfinding","tilemap"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q18','{"text":"Em uma cena 2D convencional descrita no material, as coordenadas crescem como?","options":["X para a direita e Y para baixo","X para a esquerda e Y para cima","X e Y somente para cima","X para baixo e Y para a direita","X e Y não possuem direção"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q19','{"text":"Qual conceito de programação representa uma informação que pode mudar, como a vida atual?","options":["Variável","Algoritmo","Função","Depuração","Repetição"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q20','{"text":"Na lógica booleana, o operador E exige:","options":["condições simultâneas satisfeitas","pelo menos uma condição verdadeira","inversão da condição","nenhuma condição testada","execução apenas uma vez"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q21','{"text":"Em um evento comum do GDevelop, as ações são executadas quando:","options":["as condições são satisfeitas","a cena é fechada","o projeto é exportado","todas as variáveis são globais","o profiler está aberto"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q22','{"text":"Um evento sem condições executa suas ações, normalmente:","options":["em cada quadro","uma única vez no projeto","apenas ao fechar o jogo","somente após exportação","apenas na derrota"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q23','{"text":"A condição “Trigger once” serve para:","options":["limitar a repetição contínua enquanto uma condição permanece verdadeira","gravar variáveis permanentemente","criar uma cena automaticamente","substituir qualquer temporizador","selecionar todos os objetos"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q24','{"text":"No object picking, uma condição sobre objetos pode:","options":["filtrar quais instâncias participarão das ações seguintes","converter instâncias em variáveis globais","salvar o projeto automaticamente","alterar a resolução","criar uma spritesheet"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q25','{"text":"Se apenas um dos dez cristais encosta no jogador, a lógica correta de coleta deve:","options":["agir sobre a instância selecionada que entrou em contato","apagar todos os dez cristais","somar dez pontos","reiniciar a cena","converter os cristais em objetos globais"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q26','{"text":"Qual escopo é adequado para Inimigo.Vida quando cada inimigo precisa ter sua própria vida?","options":["variável de objeto/instância","variável global única","variável de cena compartilhada obrigatoriamente","constante do projeto","temporizador global"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q27','{"text":"Segundo a apostila, uma variável global:","options":["não é automaticamente persistente depois que o jogo é fechado","é sempre gravada no disco","só pode armazenar texto","não pode ser usada entre cenas","é exclusiva de sprites"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q28','{"text":"Para deslocamento manual independente da taxa de quadros, deve-se usar:","options":["deslocamento = velocidade por segundo × tempo do quadro","deslocamento = velocidade ÷ quantidade de sprites","deslocamento = FPS × número de cenas","deslocamento = posição × volume","deslocamento = tempo do quadro ÷ velocidade"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q29','{"text":"No GDevelop, TimeDelta() fornece:","options":["o intervalo de tempo do quadro","o número total de cenas","a vida do jogador","a quantidade de objetos selecionados","o volume da música"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q30','{"text":"Por que reiniciar um temporizador em todos os quadros pode impedir que ele alcance o limite?","options":["Porque o tempo é continuamente reiniciado","Porque todas as instâncias são duplicadas","Porque a câmera é removida","Porque a variável vira texto","Porque o teclado é desativado"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q31','{"text":"No exercício de plataforma, quais comportamentos devem ser associados ao jogador e ao chão, respectivamente?","options":["personagem de plataforma e plataforma","plataforma e personagem de plataforma","pathfinding e tween","física e multiplayer","storage e partículas"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q32','{"text":"Misturar movimento manual, física e comportamento de plataforma controlando o mesmo objeto pode:","options":["produzir disputa entre sistemas de movimento","garantir maior precisão automaticamente","eliminar colisões","salvar o estado do objeto","garantir 60 FPS"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q33','{"text":"Uma máquina de estados para inimigos ajuda principalmente a:","options":["separar comportamentos como patrulhar, perseguir, atacar e morrer","substituir animações por uma imagem","exportar somente para web","eliminar condições","armazenar áudio"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q34','{"text":"Pathfinding encontra caminhos, mas a apostila destaca que ele não define:","options":["a intenção do inimigo; o projeto ainda precisa decidir o destino e a resposta","a geometria do caminho","a posição atual do objeto","a possibilidade de não existir rota","o deslocamento até o destino"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q35','{"text":"Uma interface acessível deve evitar depender exclusivamente:","options":["da cor para transmitir informação essencial","de texto legível","de contraste","de símbolos combinados com cor","de indicação de foco"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q36','{"text":"No sistema de áudio, a apostila recomenda:","options":["separar música e efeitos e controlar seus volumes de forma independente","usar um único som para todas as ações","tocar som continuamente enquanto houver contato","eliminar feedback visual quando houver áudio","usar áudio somente no menu"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q37','{"text":"Para recuperar progresso entre sessões, deve-se utilizar:","options":["armazenamento persistente planejado e recuperação dos dados","somente uma variável global","apenas object picking","uma máscara de colisão","parallax"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q38','{"text":"Se a pontuação cresce sem parar após uma única coleta, qual hipótese a apostila recomenda investigar?","options":["soma repetida por quadro","resolução muito alta","spritesheet curta","HUD em camada separada","existência de cena de vitória"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q39','{"text":"No projeto Guardião dos Cristais, tocar o portal com nove cristais deve resultar em:","options":["a fase continuar","vitória imediata","derrota imediata","reinício automático","remoção do jogador"],"correct":0}');
INSERT INTO discipline_question_bank (discipline,id,payload) VALUES ('jogos-digitais','q40','{"text":"No Guardião dos Cristais, se o jogador perder a última vida junto ao portal, qual resultado esperado foi definido?","options":["derrota, devido à prioridade definida sobre a vitória","vitória automática","empate sem transição","nova coleta automática","retorno direto ao menu"],"correct":0}');
